import java.util.*;

class Solution {
  public int maxSumDivThree(int[] nums) {
    int sum = 0;
    int[] smallest = {Integer.MAX_VALUE, Integer.MAX_VALUE};
    int[] second = {Integer.MAX_VALUE, Integer.MAX_VALUE};
    for (int x : nums) {
      sum += x;
      int r = x % 3;
      if (r == 1) {
        if (x < smallest[0]) {
          second[0] = smallest[0];
          smallest[0] = x;
        } else if (x < second[0]) second[0] = x;
      } else if (r == 2) {
        if (x < smallest[1]) {
          second[1] = smallest[1];
          smallest[1] = x;
        } else if (x < second[1]) second[1] = x;
      }
    }
    int r = sum % 3;
    if (r == 1) {
      int remove = smallest[0];
      if (second[1] != Integer.MAX_VALUE) remove = Math.min(remove, second[1]);
      return remove == Integer.MAX_VALUE ? 0 : sum - remove;
    }
    if (r == 2) {
      int remove = smallest[1];
      if (second[0] != Integer.MAX_VALUE) remove = Math.min(remove, second[0]);
      return remove == Integer.MAX_VALUE ? 0 : sum - remove;
    }
    return sum;
  }
}
